const geologicalWonders=[{id:1,name:"Lonar Crater",location:"Maharashtra",type:"crater",icon:"🌋",description:"A meteorite impact crater lake formed around 52,000 years ago, one of the world's few basaltic impact craters.",history:"The Lonar Crater was created by a meteor impact approximately 52,000 years ago during the Pleistocene epoch. It is the only known impact crater in basaltic rock on Earth. The crater has a diameter of 1.8 kilometers and a depth of 137 meters. The lake inside the crater is both saline and alkaline, making it a unique ecosystem.",formation:"Formed by high-velocity meteor impact that penetrated the Deccan Traps basalt layers. The impact created a bowl-shaped depression that gradually filled with water, creating a unique lake with unusual chemical properties.",significance:["Only hyper-velocity impact crater in basaltic rock on Earth","Lake has both saline and alkaline properties","Home to unique microbial ecosystems","Important site for studying impact cratering processes","Sacred site with several ancient temples around the rim"],mapUrl:"https://www.google.com/maps/search/?api=1&query=Lonar+Crater+Maharashtra"},{id:2,name:"Marble Rocks",location:"Madhya Pradesh",type:"rock",icon:"🗿",description:"Stunning white marble cliffs along the Narmada River, rising to 100 feet in height.",history:"The Marble Rocks at Bhedaghat have been carved by the Narmada River over millions of years. These stunning white marble formations have been a popular tourist destination since the British colonial era. The area is famous for its boat rides through the marble gorges, especially during moonlight when the rocks glow ethereally.",formation:"The marble rocks are part of the Vindhya Supergroup, formed from metamorphosed limestone deposits. The Narmada River has carved these soft marble formations over geological time, creating spectacular cliffs and gorges with smooth, polished surfaces.",significance:["100-foot tall white marble cliffs","Beautiful boat rides through marble gorges","Spectacular during full moon nights","Featured in several Bollywood films","Geological window into ancient marine environments"],mapUrl:"https://www.google.com/maps/search/?api=1&query=Marble+Rocks+Bhedaghat+Madhya+Pradesh"},{id:3,name:"Gandikota",location:"Andhra Pradesh",type:"canyon",icon:"🏜️",description:"Known as the 'Grand Canyon of India', featuring spectacular gorges carved by the Pennar River.",history:"Gandikota was established as a fort in the 12th century and served as the capital of the Pemmasani Nayaks. The geological wonder lies in the stunning gorge formed by the Pennar River cutting through the Erramala hills, creating canyon walls that rise hundreds of feet.",formation:"The canyon was formed by the Pennar River eroding through quartzite and granite rock formations of the Eastern Ghats over millions of years. The hard, resistant rock created steep canyon walls while the river carved a deep channel through the landscape.",significance:["Called the 'Grand Canyon of India'","Canyon walls rise 300-400 feet","Ancient fort complex with historical temples","Unique geological formation in peninsular India","Spectacular sunset views over the gorge"],mapUrl:"https://www.google.com/maps/search/?api=1&query=Gandikota+Andhra+Pradesh"},{id:4,name:"Barren Island",location:"Andaman Sea",type:"volcanic",icon:"🔥",description:"India's only active volcano, located in the Andaman Sea, with a history of eruptions spanning centuries.",history:"Barren Island is India's only active volcano and the only confirmed active volcano in South Asia. The first recorded eruption was in 1787, and it has erupted multiple times since, with recent activity in 2017-2018. The island is uninhabited due to its volcanic nature.",formation:"Part of the volcanic arc formed by the subduction of the Indian Plate beneath the Burmese Plate. The stratovolcano rises from the ocean floor to an elevation of 354 meters above sea level. The volcanic activity is directly linked to tectonic plate movements in this region.",significance:["India's only active volcano","Only confirmed active volcano in South Asia","Stratovolcano rising from ocean floor","Important for studying volcanic activity","Unique marine ecosystem around volcanic vents"],mapUrl:"https://www.google.com/maps/search/?api=1&query=Barren+Island+Andaman+Sea"},{id:5,name:"Columnar Basalt Formations",location:"St. Mary's Islands, Karnataka",type:"rock",icon:"🪨",description:"Hexagonal basalt columns created by volcanic cooling, similar to the Giant's Causeway in Ireland.",history:"The St. Mary's Islands, also known as Coconut Island, are famous for their distinctive hexagonal basalt columns. These formations were declared a National Geological Monument in 2001. The islands are among the few places in the world where columnar jointing in basalt is so prominently displayed.",formation:"The columnar basalt formations were created during the Deccan Traps volcanic activity around 88 million years ago. As thick lava flows cooled and contracted, they cracked in a hexagonal pattern, creating the distinctive vertical columns. The columns are typically 3-6 feet in diameter and can be up to 20 feet tall.",significance:["National Geological Monument since 2001","Hexagonal basalt columns similar to Giant's Causeway","Formed during Deccan Traps volcanic activity","Excellent example of columnar jointing","Rare geological formation in India"],mapUrl:"https://www.google.com/maps/search/?api=1&query=St+Mary's+Islands+Karnataka"}];let currentFilter="all",searchQuery="";function createWonderCard(e){const a=document.createElement("div");return a.className="wonder-card",a.dataset.type=e.type,a.dataset.id=e.id,a.innerHTML=`\n        <div class="wonder-image">${e.icon}</div>\n        <div class="wonder-content">\n            <h3>${e.name}</h3>\n            <div class="location">📍 ${e.location}</div>\n            <span class="type">${e.type.charAt(0).toUpperCase()+e.type.slice(1)}</span>\n            <p>${e.description}</p>\n        </div>\n    `,a.addEventListener("click",()=>openModal(e)),a}function renderWonders(){const e=document.getElementById("wondersGrid");e.innerHTML="";geologicalWonders.filter(e=>{const a="all"===currentFilter||e.type===currentFilter,n=e.name.toLowerCase().includes(searchQuery.toLowerCase())||e.location.toLowerCase().includes(searchQuery.toLowerCase())||e.description.toLowerCase().includes(searchQuery.toLowerCase());return a&&n}).forEach(a=>{e.appendChild(createWonderCard(a))})}function openModal(e){const a=document.getElementById("modal");document.getElementById("modalBody").innerHTML=`\n        <div class="modal-header">\n            <h2>${e.name}</h2>\n            <div class="location">📍 ${e.location}</div>\n        </div>\n        <div class="modal-image">${e.icon}</div>\n        <div class="modal-section">\n            <h3>Description</h3>\n            <p>${e.description}</p>\n        </div>\n        <div class="modal-section">\n            <h3>Geological History</h3>\n            <p>${e.history}</p>\n        </div>\n        <div class="modal-section">\n            <h3>Formation Process</h3>\n            <p>${e.formation}</p>\n        </div>\n        <div class="modal-section">\n            <h3>Significance</h3>\n            <ul>\n                ${e.significance.map(e=>`<li>${e}</li>`).join("")}\n            </ul>\n        </div>\n        <a href="${e.mapUrl}" target="_blank" class="map-link">🗺️ View on Google Maps</a>\n    `,a.classList.add("show"),document.body.style.overflow="hidden"}function closeModal(){document.getElementById("modal").classList.remove("show"),document.body.style.overflow="auto"}function setupEventListeners(){document.getElementById("searchInput").addEventListener("input",e=>{searchQuery=e.target.value,renderWonders()});const e=document.querySelectorAll(".filter-btn");e.forEach(a=>{a.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),a.classList.add("active"),currentFilter=a.dataset.filter,renderWonders()})});document.querySelector(".close").addEventListener("click",closeModal);const a=document.getElementById("modal");a.addEventListener("click",e=>{e.target===a&&closeModal()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&closeModal()})}document.addEventListener("DOMContentLoaded",()=>{renderWonders(),setupEventListeners()});